/**
 * A fixed-capacity least-recently-used cache.
 *
 * Entries live in a doubly linked list backed by typed arrays (index 0 is the
 * sentinel), with a Map from key to node index. Every operation is O(1).
 */
export class LruCache<V> {
  readonly capacity: number;

  readonly #index = new Map<string, number>();
  readonly #keys: string[];
  readonly #values: (V | undefined)[];
  readonly #prev: Int32Array;
  readonly #next: Int32Array;
  #free: number[] = [];
  #allocated = 1;

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError(`capacity must be a positive integer, got ${capacity}`);
    }
    this.capacity = capacity;
    // One extra slot for the sentinel and one for the transient overflow entry.
    const slots = capacity + 2;
    this.#keys = new Array<string>(slots);
    this.#values = new Array<V | undefined>(slots);
    this.#prev = new Int32Array(slots);
    this.#next = new Int32Array(slots);
  }

  get size(): number {
    return this.#index.size;
  }

  /** Returns the value for `key`, marking it most recently used, or undefined. */
  get(key: string): V | undefined {
    const node = this.#index.get(key);
    if (node === undefined) return undefined;
    this.#unlink(node);
    this.#pushFront(node);
    return this.#values[node];
  }

  /** Inserts or overwrites `key`, marking it most recently used; evicts if over capacity. */
  set(key: string, value: V): void {
    const existing = this.#index.get(key);
    if (existing !== undefined) {
      this.#values[existing] = value;
      this.#unlink(existing);
      this.#pushFront(existing);
      return;
    }
    const node = this.#allocate();
    this.#keys[node] = key;
    this.#values[node] = value;
    this.#index.set(key, node);
    this.#pushFront(node);
    if (this.#index.size > this.capacity) {
      this.#remove(this.#prev[0]);
    }
  }

  /** Removes `key`; returns whether it was present. */
  delete(key: string): boolean {
    const node = this.#index.get(key);
    if (node === undefined) return false;
    this.#remove(node);
    return true;
  }

  #allocate(): number {
    return this.#free.pop() ?? this.#allocated++;
  }

  #remove(node: number): void {
    this.#unlink(node);
    this.#index.delete(this.#keys[node]);
    this.#keys[node] = "";
    this.#values[node] = undefined;
    this.#free.push(node);
  }

  #unlink(node: number): void {
    const prev = this.#prev[node];
    const next = this.#next[node];
    this.#next[prev] = next;
    this.#prev[next] = prev;
  }

  #pushFront(node: number): void {
    const first = this.#next[0];
    this.#prev[node] = 0;
    this.#next[node] = first;
    this.#prev[first] = node;
    this.#next[0] = node;
  }
}

/**
 * Simulate an LRU cache driven by commands on standard input.
 *
 * Input: the capacity on the first line, then one command per line:
 * `SET <key> <value>`, `GET <key>`, `DEL <key>` or `SIZE`.
 */
import { readFileSync, writeSync } from "node:fs";
import { LruCache } from "./lru-cache.ts";

const NULL = "NULL";
const WHITESPACE = /[ \t\n\r\v\f]+/;

/** Executes cache commands, returning one output line per producing command. */
export function run(capacity: number, lines: Iterable<string>): string[] {
  const cache = new LruCache<string>(capacity);
  const out: string[] = [];

  for (const line of lines) {
    const parts = line.trim().split(WHITESPACE);
    const [cmd, key, value] = parts;
    switch (cmd) {
      case "SET":
        if (key !== undefined && value !== undefined) cache.set(key, value);
        break;
      case "GET":
        if (key !== undefined) out.push(cache.get(key) ?? NULL);
        break;
      case "DEL":
        if (key !== undefined) out.push(cache.delete(key) ? "1" : "0");
        break;
      case "SIZE":
        out.push(String(cache.size));
        break;
      default:
        // Blank lines and unknown commands are ignored.
        break;
    }
  }
  return out;
}

function writeAll(text: string): void {
  const buf = Buffer.from(text, "latin1");
  let offset = 0;
  while (offset < buf.length) {
    try {
      offset += writeSync(1, buf, offset);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "EAGAIN") throw err;
    }
  }
}

function main(): number {
  const lines = readFileSync(0, "latin1").split("\n");
  const header = lines[0]?.trim() ?? "";
  if (header === "") return 0;

  const capacity = Number(header);
  if (!Number.isInteger(capacity) || capacity < 1) {
    process.stderr.write(`invalid capacity: ${header}\n`);
    return 1;
  }

  const out = run(capacity, lines.slice(1));
  if (out.length > 0) writeAll(out.join("\n") + "\n");
  return 0;
}

process.exitCode = main();
